import math
from sklearn.model_selection import train_test_split
from sklearn.neighbors import KNeighborsClassifier


def scale_columns(rows):
    if len(rows) == 0:
        return []
    column_count = len(rows[0])
    smallest = [min(row[i] for row in rows) for i in range(column_count)]
    largest = [max(row[i] for row in rows) for i in range(column_count)]
    scaled = []
    for row in rows:
        new_row = []
        for i in range(column_count):
            value = row[i]
            if largest[i] == smallest[i]:
                new_row.append(0.0)
            else:
                new_row.append((value - smallest[i]) / (largest[i] - smallest[i]))
        scaled.append(new_row)
    return scaled


def nearest_label(X, y, point):
    best_index = 0
    best_distance = math.dist(X[0], point)
    for i in range(1, len(X)):
        distance = math.dist(X[i], point)
        if distance < best_distance:
            best_distance = distance
            best_index = i
    return y[best_index]


def knn_predict(X, y, rows, k):
    if k > len(X):
        raise ValueError('k is larger than the number of known stars')
    if len(rows) == 0:
        return []
    model = KNeighborsClassifier(n_neighbors=k)
    model.fit(X, y)
    return list(model.predict(rows))


